package ro.leo.visual;
import android.content.*;
import android.os.Bundle;
import java.util.*;
public final class PersonalizationActivity extends LeoActivity {
    protected void onCreate(Bundle state){super.onCreate(state);if(getIntent().getBooleanExtra("order",false))order(0);else home();}
    private void home(){list("Personalizare",Arrays.asList("Ordinea aplicațiilor","Scurtături pe Home","Dimensiunea textului","Notificări pe ecranul blocat","Fundaluri și teme","Profiluri sonore","Favorite și apelare rapidă","Home · ceas și informații"),0,new Choice(){public void pick(int i){if(i==0)order(0);else if(i==1)shortcuts();else if(i==2)options("Text",new String[]{"Normal","Mai mare"},new Choice(){public void pick(int n){getSharedPreferences("appearance",0).edit().putBoolean("large-text",n==1).apply();home();}});else if(i==3)previews();else if(i==4)startActivity(new Intent(PersonalizationActivity.this,WallpaperActivity.class));else if(i==5)SoundProfiles.select(PersonalizationActivity.this,new Runnable(){public void run(){home();}});else if(i==7)homeLayout();else startActivity(new Intent(PersonalizationActivity.this,SpeedDialActivity.class));}},"",null);}
    private void homeLayout(){final android.content.SharedPreferences p=getSharedPreferences("appearance",0);final String[] keys={"home-compact","home-sims","home-unread","home-dbm"};final String[] labels={"Ceas compact","Starea ambelor SIM-uri","Contoare SMS / apeluri","Semnal în dBm"};ArrayList<String> rows=new ArrayList<String>();for(int i=0;i<keys.length;i++)rows.add(labels[i]+" · "+(p.getBoolean(keys[i],i!=0)?"Da":"Nu"));list("Aspect Home",rows,0,new Choice(){public void pick(int i){p.edit().putBoolean(keys[i],!p.getBoolean(keys[i],i!=0)).apply();homeLayout();}},"Resetează",new Runnable(){public void run(){android.content.SharedPreferences.Editor e=p.edit();for(String key:keys)e.remove(key);e.apply();homeLayout();}});back=new Runnable(){public void run(){home();}};}
    private void order(int selected){final int[] ids=AppCatalog.order(this);ArrayList<String> labels=new ArrayList<String>();for(int id:ids)labels.add(AppCatalog.NAMES[id]);list("Ordinea aplicațiilor",labels,selected,new Choice(){public void pick(final int at){options(AppCatalog.NAMES[ids[at]],new String[]{"Mută mai sus","Mută mai jos","Mută la început","Înapoi"},new Choice(){public void pick(int action){int target=action==0?Math.max(0,at-1):action==1?Math.min(ids.length-1,at+1):action==2?0:at;int id=ids[at];if(target<at)System.arraycopy(ids,target,ids,target+1,at-target);else if(target>at)System.arraycopy(ids,at+1,ids,at,target-at);ids[target]=id;AppCatalog.save(PersonalizationActivity.this,ids);order(target);}});}},"Resetează",new Runnable(){public void run(){options("Resetezi ordinea?",new String[]{"Păstrează","Resetează"},new Choice(){public void pick(int i){if(i==1){getSharedPreferences("appearance",0).edit().remove("app-order").apply();order(0);}}});}});back=new Runnable(){public void run(){home();}};}
    private void shortcuts(){int[] ids=AppCatalog.shortcuts(this);ArrayList<String> labels=new ArrayList<String>();for(int i=0;i<ids.length;i++)labels.add((i+1)+" · "+AppCatalog.NAMES[ids[i]]);list("Scurtături Home",labels,0,new Choice(){public void pick(final int slot){list("Alege aplicația",Arrays.asList(AppCatalog.NAMES),0,new Choice(){public void pick(int id){getSharedPreferences("appearance",0).edit().putInt("shortcut"+slot,id).apply();shortcuts();}},"",null);back=new Runnable(){public void run(){shortcuts();}};}},"",null);back=new Runnable(){public void run(){home();}};}
    private void previews(){list("Notificări la blocare",Arrays.asList("Ascunde previzualizările","Afișează titlurile","Afișează titlul și textul"),getSharedPreferences("appearance",0).getInt("lock-preview",0),new Choice(){public void pick(final int mode){if(mode==2)options("Text vizibil fără deblocare",new String[]{"Anulează","Permite previzualizarea"},new Choice(){public void pick(int yes){if(yes==1)savePreview(mode);}});else savePreview(mode);}},"",null);back=new Runnable(){public void run(){home();}};}
    private void savePreview(int mode){getSharedPreferences("appearance",0).edit().putInt("lock-preview",mode).apply();notice("Preferința notificărilor salvată");home();}
}
